from typing import Dict, Any


def agregar_vendas(relatorio: Dict[str, Dict[str, int]]) -> int:
    """Soma quantidades de um relatório de vendas aninhado."""
    total = 0
    for departamento in relatorio.values():
        for quantidade in departamento.values():
            total += quantidade
    return total

def memoizar(func):
    cache = {}

    def wrapper(*args):
        if args not in cache:
            cache[args] = func(*args)
        return cache[args]

    return wrapper


@memoizar
def enriquecer_lote(itens):
    for i, item in enumerate(itens):
        itens[i] = item + '_ok'
    return itens

from copy import deepcopy


def mesclar_config(base: dict, overrides: dict) -> dict:
    config = base
    for chave, valor in overrides.items():
        if isinstance(valor, dict) and chave in config and isinstance(config[chave], dict):
            config[chave].update(valor)
        else:
            config[chave] = valor
    return config

def parse_registros(linhas):
    registros = []
    for linha in linhas:
        partes = linha.split('|')
        if len(partes) < 3:
            continue
        registros.append({
            'id': int(partes[0]),
            'nome': partes[1],
            'valor': float(partes[2]),
        })
    return registros

from typing import List, Optional


def calcular_estatisticas(valores: List[float]) -> dict:
    if not valores:
        return {
            'media': 0.0,
            'minimo': None,
            'maximo': None,
            'total': 0,
        }
    return {
        'media': sum(valores) / len(valores),
        'minimo': min(valores),
        'maximo': max(valores),
        'total': len(valores),
    }

def expandir_intervalo(inicio: int, fim: int) -> list:
    if fim < inicio:
        raise ValueError('Intervalo inválido')
    resultado = []
    atual = inicio
    while atual <= fim:
        resultado.append(atual)
        atual += 1
    return resultado

from typing import Any, List, Optional


def buscar_caminho(no: dict, caminho: List[str]) -> Optional[Any]:
    atual = no
    for chave in caminho:
        atual = atual[chave]
    return atual
